import React from 'react';

export default function StudioFooter() {
    return (
        <footer className="footer">
            <div className="container">
                <div className="row">
                    <div className="col-12 text-center">
                        {new Date().getFullYear()} &copy; Studio Platform. All rights reserved.
                    </div>
                </div>
            </div>
        </footer>
    );
}
